import {request} from '../cms-api.js';
export async function renderRequests(container,online){
 const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
 const heading=el('p','Visitor-confirmed enquiries. Replies open in your email app; nothing is emailed automatically.');container.append(heading);
 if(!online){container.append(el('p','Sign in as the owner to load requests.'));return;}
 const controls=document.createElement('div'),filter=document.createElement('select');filter.setAttribute('aria-label','Request status');for(const k of ['all','new','reviewing','replied','closed']){const o=el('option',k);o.value=k;filter.append(o);}const refresh=el('button','Refresh');controls.append(filter,refresh);container.append(controls);
 const status=el('p','Loading requests…');status.setAttribute('role','status');container.append(status);const list=document.createElement('div');container.append(list);
 async function load(){list.replaceChildren();status.textContent='Loading requests…';try{const rows=await request('/rest/v1/portfolio_requests?select=id,name,email,category,subject,message,status,created_at&order=created_at.desc&limit=100'+(filter.value==='all'?'':'&status=eq.'+filter.value),{},true);status.textContent=rows.length?rows.length+' recent requests':'No requests in this view yet.';for(const row of rows){const card=el('article','');card.className='panel';card.append(el('h2',row.subject),el('p',row.name+' · '+row.email+' · '+row.category),el('p',new Date(row.created_at).toLocaleString()));const body=el('p',row.message);body.style.whiteSpace='pre-wrap';card.append(body);const select=document.createElement('select');select.setAttribute('aria-label','Status for '+row.subject);for(const k of ['new','reviewing','replied','closed']){const o=el('option',k);o.value=k;o.selected=row.status===k;select.append(o);}select.onchange=async()=>{select.disabled=true;try{const updated=await request('/rest/v1/portfolio_requests?id=eq.'+row.id,{method:'PATCH',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify({status:select.value})},true);if(updated?.length!==1)throw Error('Request was not updated. Refresh and try again.');row.status=select.value;status.textContent='Request status updated.';}catch(e){select.value=row.status;status.textContent=e.message;}finally{select.disabled=false;}};card.append(select);const reply=el('a','Reply by email ↗');reply.href='mailto:'+encodeURIComponent(row.email)+'?subject='+encodeURIComponent('Re: '+row.subject);reply.style.display='inline-block';reply.style.padding='16px';card.append(reply);const del=el('button','Delete request');del.onclick=async()=>{if(!confirm('Permanently delete this request and its contact details?'))return;try{await request('/rest/v1/portfolio_requests?id=eq.'+row.id,{method:'DELETE'},true);card.remove();status.textContent='Request deleted.';}catch(e){status.textContent=e.message;}};card.append(del);list.append(card);}}catch(e){status.textContent='Could not load requests: '+e.message;}}
 filter.onchange=load;refresh.onclick=load;await load();
}
